```typescript
// 假设这些变量已经定义
const c: number = 3e8; // 光速，单位为米/秒
const M_sun: number = 1.989e30; // 太阳的质量，单位为千克
const L_sun: number = 3.828e26; // 太阳的光度，单位为瓦特
const M: number = 0; // 初始核心质量，单位为太阳质量

// 假设这些函数已经定义
function luminosity(M_core: number): number {
    return (10 ** 5 * L_sun) / (M_sun ** 6) * M_core ** 6;
}

function energy_conversion(delta_M_core: number): number {
    return 0.007 * delta_M_core * c ** 2;
}

// 使用这些函数来建立微分方程
function differential_equation(t: number, M: number): number {
    const dM_dt: number = (luminosity(M) - energy_conversion(M)) / M;
    return dM_dt;
}

// 示例时间步长和初始条件
const dt: number = 1; // 时间步长，单位为秒
const t_end: number = 1000; // 终止时间，单位为秒
const M_initial: number = 0.001 * M_sun; // 初始核心质量，单位为太阳质量

// 使用欧拉方法求解微分方程
function euler_method(t: number, M: number, dt: number, t_end: number, M_initial: number): number {
    const t_max: number = t_end;
    const M_final: number = M_initial;
    const M_values: number[] = [M_initial];

    while (t < t_max) {
        const dM_dt: number = differential_equation(t, M_values[t % 100]);
        M_values.push(M_values[t % 100] + dM_dt * dt);
        t += dt;
    }

    return M_final;
}

// 计算最终核心质量
const final_M_core: number = euler_method(0, M_initial, dt, t_end, M_initial);
console.log(`最终核心质量为: ${final_M_core} 太阳质量`);

